 code=f'''import vail as h,time,resource,json
h.eval(0);mode={mode!r};size={size}
if mode=='scan':
 t=h.range_table(0);value=h.scan.sum(t.idx)
 for _ in range(size):value=value+value
 start=time.perf_counter();result=t.annotate(prefix=h.scan.filter(True,value));elapsed=time.perf_counter()-start;assert result.prefix.dtype==h.tint64;check={{'field':'prefix','type':'int64'}}
elif mode in ('dag','action'):
 source=h.range_table(0).annotate_globals(g=1);g=source.index_globals().g
 for _ in range(size):g=g+g
 t=h.range_table(0)
 if mode=='dag':
  start=time.perf_counter();result=t.annotate_globals(value=g);elapsed=time.perf_counter()-start;assert result.globals.dtype==h.tstruct(value=h.tint32);check={{'field':'value','type':'int32'}}
 else:
  result=t.annotate_globals(value=g);start=time.perf_counter();answer=h.eval(result.value);elapsed=time.perf_counter()-start;assert answer==2**size;check={{'value':answer}}
else:
 t=h.range_table(0).annotate_globals(**{{'g'+str(i):i for i in range(size)}})
 start=time.perf_counter()
 if mode=='wide':result=t.annotate_globals(new=1);fields=result.globals;elapsed=time.perf_counter()-start;assert len(fields.dtype)==size+1;check={{'fields':len(fields.dtype)}}
 elif mode=='wide_action':
  result=h.eval(t.globals);elapsed=time.perf_counter()-start;assert len(result)==size and sum(result.values())==size*(size-1)//2;check={{'fields':len(result),'sum':sum(result.values())}}
 else:
  bad=t.annotate_globals(bad=h.array([1])[5]);result=bad.select_globals();r=h.eval(result.index_globals());elapsed=time.perf_counter()-start;assert r==h.Struct();check={{'fields':0}}
print(json.dumps(dict(construction_seconds=elapsed,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,check=check)))'''
 try:
  r=subprocess.run([root+'/.venv/bin/python','-c',code],cwd='/tmp',env=dict(os.environ,PYTHONPATH=path),capture_output=True,text=True,timeout=15)
  result=json.loads(r.stdout) if not r.returncode else dict(error=r.stderr[-1500:])
 except subprocess.TimeoutExpired:result=dict(timeout_seconds=15)
 cases.append(dict(version=version,mode=mode,size=size,**result))
